cat > /app/output/styles.css << 'EOF'
:root {
  --primary: #1f3dff;
  --primary-dark: #1026b8;
  --accent: #00d084;
  --accent-2: #ff5f7a;
  --text: #0f172a;
  --muted: #475569;
  --bg: #ffffff;
  --surface: #f8fafc;
  --card: #ffffff;
  --border: #e2e8f0;
  --shadow: 0 14px 40px rgba(15, 23, 42, 0.08);
  --radius: 16px;
}

* { box-sizing: border-box; }
html { scroll-behavior: smooth; }
body {
  margin: 0;
  font-family: Inter, "Plus Jakarta Sans", system-ui, -apple-system, sans-serif;
  color: var(--text);
  background: var(--bg);
  line-height: 1.6;
}
.container { width: min(1120px, 92vw); margin: 0 auto; }
.section { padding: 72px 0; }
.muted { color: var(--muted); }

h1,h2,h3,h4 { line-height: 1.15; margin: 0 0 14px; letter-spacing: -0.02em; }
h1 { font-size: clamp(2rem, 4.2vw, 3.4rem); }
h2 { font-size: clamp(1.7rem, 3.1vw, 2.4rem); }
h3 { font-size: 1.2rem; }
p { margin: 0 0 12px; }

.btn {
  border: 0;
  border-radius: 999px;
  padding: 12px 20px;
  font-weight: 700;
  cursor: pointer;
  text-decoration: none;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  transition: .2s ease;
}
.btn-primary { background: var(--primary); color: #fff; }
.btn-primary:hover { background: var(--primary-dark); transform: translateY(-1px); }
.btn-ghost { background: #eef2ff; color: var(--primary); }
.btn-ghost:hover { background: #dbe3ff; }

.nav {
  position: sticky;
  top: 0;
  z-index: 50;
  background: rgba(255,255,255,.92);
  backdrop-filter: blur(8px);
  border-bottom: 1px solid var(--border);
}
.nav-inner { display: flex; align-items: center; justify-content: space-between; gap: 18px; padding: 14px 0; }
.brand { font-weight: 900; font-size: 1.12rem; color: var(--text); text-decoration: none; }
.nav-links { display: flex; gap: 14px; flex-wrap: wrap; }
.nav-links a { text-decoration: none; color: var(--muted); font-weight: 600; padding: 8px 10px; border-radius: 10px; }
.nav-links a:hover, .nav-links a.active { color: var(--primary); background: #eef2ff; }

.hero {
  padding: 72px 0 40px;
  background: radial-gradient(circle at 10% 10%, #eef2ff 0, transparent 44%),
              radial-gradient(circle at 90% 20%, #d1fae5 0, transparent 35%);
}
.hero-grid { display: grid; grid-template-columns: 1.1fr .9fr; gap: 28px; align-items: center; }

.tabs, .feature-tabs { display: flex; gap: 10px; flex-wrap: wrap; }
.tab-btn, .feature-tab-btn {
  border: 1px solid var(--border);
  background: #fff;
  color: var(--muted);
  font-weight: 700;
  border-radius: 999px;
  padding: 9px 14px;
  cursor: pointer;
}
.tab-btn.active, .feature-tab-btn.active { background: var(--text); color: #fff; border-color: var(--text); }
.preview-card, .card {
  background: var(--card);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  box-shadow: var(--shadow);
  padding: 22px;
}

.grid { display: grid; gap: 18px; }
.grid-2 { grid-template-columns: repeat(2, minmax(0, 1fr)); }
.grid-3 { grid-template-columns: repeat(3, minmax(0, 1fr)); }
.grid-4 { grid-template-columns: repeat(4, minmax(0, 1fr)); }

.stats {
  background: var(--text);
  color: #fff;
  border-radius: 20px;
  margin-top: 22px;
  padding: 16px;
}
.stat { text-align: center; padding: 10px; }
.stat strong { display: block; font-size: 1.7rem; color: var(--accent); }

.integration-logo {
  border: 1px solid var(--border);
  background: #fff;
  border-radius: 12px;
  padding: 14px;
  text-align: center;
  font-weight: 700;
}

.faq-item { border: 1px solid var(--border); border-radius: 12px; margin-bottom: 10px; overflow: hidden; }
.faq-q {
  width: 100%; text-align: left; border: 0; background: #fff; padding: 14px 16px;
  font-size: 1rem; font-weight: 700; cursor: pointer; color: var(--text);
}
.faq-a { max-height: 0; overflow: hidden; transition: max-height .25s ease; padding: 0 16px; }
.faq-item.open .faq-a { max-height: 260px; padding: 0 16px 14px; }

.carousel { position: relative; }
.carousel-track { display: grid; grid-template-columns: 1fr; }
.slide { display: none; }
.slide.active { display: block; }
.carousel-controls { display: flex; gap: 10px; margin-top: 12px; }

.reveal { opacity: 0; transform: translateY(16px); transition: .45s ease; }
.reveal.show { opacity: 1; transform: translateY(0); }

footer { background: var(--text); color: #cbd5e1; padding: 38px 0; margin-top: 52px; }
footer a { color: #fff; text-decoration: none; }

@media (max-width: 900px) {
  .hero-grid { grid-template-columns: 1fr; }
  .grid-4 { grid-template-columns: repeat(2, minmax(0, 1fr)); }
  .grid-3 { grid-template-columns: 1fr; }
}
@media (max-width: 640px) {
  .grid-2, .grid-4 { grid-template-columns: 1fr; }
  .nav-links { display: none; }
}
EOF

cat > /app/output/script.js << 'EOF'
document.querySelectorAll('.tab-btn').forEach(btn => {
  btn.addEventListener('click', () => {
    const wrap = btn.closest('[data-tab-wrap]');
    wrap.querySelectorAll('.tab-btn').forEach(b => b.classList.remove('active'));
    btn.classList.add('active');
    const key = btn.dataset.tab;
    wrap.querySelectorAll('[data-tab-panel]').forEach(panel => {
      panel.style.display = panel.dataset.tabPanel === key ? 'block' : 'none';
    });
  });
});

document.querySelectorAll('.feature-tab-btn').forEach(btn => {
  btn.addEventListener('click', () => {
    const wrap = btn.closest('[data-feature-wrap]');
    wrap.querySelectorAll('.feature-tab-btn').forEach(b => b.classList.remove('active'));
    btn.classList.add('active');
    const key = btn.dataset.feature;
    wrap.querySelectorAll('[data-feature-panel]').forEach(panel => {
      panel.style.display = panel.dataset.featurePanel === key ? 'block' : 'none';
    });
  });
});

document.querySelectorAll('.faq-item').forEach(item => {
  item.querySelector('.faq-q').addEventListener('click', () => {
    item.classList.toggle('open');
  });
});

document.querySelectorAll('[data-carousel]').forEach(carousel => {
  const slides = [...carousel.querySelectorAll('.slide')];
  let i = 0;
  const show = idx => slides.forEach((s, n) => s.classList.toggle('active', idx === n));
  carousel.querySelector('.next').addEventListener('click', () => { i = (i + 1) % slides.length; show(i); });
  carousel.querySelector('.prev').addEventListener('click', () => { i = (i - 1 + slides.length) % slides.length; show(i); });
  show(0);
});

const obs = new IntersectionObserver(entries => {
  entries.forEach(e => { if (e.isIntersecting) e.target.classList.add('show'); });
}, { threshold: .14 });
document.querySelectorAll('.reveal').forEach(el => obs.observe(el));
EOF

